package cn.gmiya.malodylink;

import android.app.*;
import android.content.Context;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public final class RankingPanel extends LinearLayout {
    private final Runnable home;private final Activity host;private final Engine engine;private final BiConsumer<Boolean,Integer> remember;private final Consumer<String> searchMemory;private String searchQuery;
    private final ExecutorService io=Executors.newSingleThreadExecutor();private volatile boolean closed;private boolean single,loading;private int cid,loadGeneration;private RankingRepository.Snapshot snapshot;private TextView status;private Button refresh;private ListView list;
    public RankingPanel(Activity host,Engine engine,boolean single,int cid,String query,BiConsumer<Boolean,Integer> remember,Consumer<String> searchMemory){this(host,engine,single,cid,query,remember,searchMemory,null);}
    public RankingPanel(Activity host,Engine engine,boolean single,int cid,String query,BiConsumer<Boolean,Integer> remember,Consumer<String> searchMemory,Runnable home){super(host);this.home=home;this.host=host;this.engine=engine;this.single=single;this.cid=cid;this.searchQuery=query;this.remember=remember;this.searchMemory=searchMemory;setOrientation(1);setBackground(new CharacterBackdrop(host,2));setPadding(AppUi.dp(host,16),AppUi.dp(host,16),AppUi.dp(host,16),0);build();load(false);}
    private void build(){removeAllViews();addView(AppUi.text(host,home==null?"排行榜":"单曲榜",26,AppUi.INK,true));LinearLayout tabs=new LinearLayout(host);Button total=AppUi.button(host,home==null?"总战力":"榜单首页",()->{if(home!=null)home.run();else mode(false,0);});Button singleButton=AppUi.button(host,"单曲榜",()->mode(true,cid));total.setSelected(!single);singleButton.setSelected(single);total.setTextColor(single?AppUi.INK:AppUi.ON_SUCCESS);singleButton.setTextColor(single?AppUi.ON_SUCCESS:AppUi.INK);total.setBackgroundTintList(android.content.res.ColorStateList.valueOf(single?AppUi.SOFT:AppUi.ACCENT));singleButton.setBackgroundTintList(android.content.res.ColorStateList.valueOf(single?AppUi.ACCENT:AppUi.SOFT));tabs.addView(total,new LayoutParams(0,-2,1));LayoutParams right=new LayoutParams(0,-2,1);right.leftMargin=AppUi.dp(host,8);tabs.addView(singleButton,right);addView(tabs);status=AppUi.text(host,loading?"读取云端成绩…":"",12,AppUi.MUTED,false);status.setPadding(0,AppUi.dp(host,8),0,AppUi.dp(host,8));addView(status);refresh=AppUi.button(host,"刷新排行榜",()->load(true));refresh.setEnabled(!loading);addView(refresh);
        if(single&&cid==0){list=null;SongPanel chooser=new SongPanel(host,engine,searchQuery,q->{searchQuery=q;searchMemory.accept(q);},(s,id)->mode(true,id),true);addView(chooser,new LayoutParams(-1,0,1));}
        else{if(single){SongCatalogue.Song song=new SongCatalogue(engine.charts()).forChart(cid);if(song==null){cid=0;remember.accept(true,0);build();return;}TextView title=AppUi.text(host,song.title,18,AppUi.INK,true);title.setMaxLines(2);addView(title);Spinner difficulty=new Spinner(host);String[] labels=new String[song.charts.size()];int checked=0;for(int i=0;i<labels.length;i++){JSONObject c=song.charts.get(i);labels[i]=SongCatalogue.levelLabel(c)+" · "+ChartKeys.label(c)+" · "+c.optString("version");if(c.optInt("cid")==cid)checked=i;}ArrayAdapter<String> adapter=new ArrayAdapter<>(host,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);difficulty.setAdapter(adapter);difficulty.setSelection(checked,false);difficulty.setMinimumHeight(AppUi.dp(host,48));difficulty.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int pos,long id){int chosen=song.charts.get(pos).optInt("cid");if(chosen!=cid){cid=chosen;remember.accept(true,cid);load(false);}}});addView(difficulty);addView(AppUi.button(host,"搜索其他歌曲",()->mode(true,0)));}
            else{TextView note=AppUi.text(host,"O20 + N10 综合 rating · 统一默认规则",13,AppUi.MUTED,false);note.setPadding(0,AppUi.dp(host,8),0,AppUi.dp(host,8));addView(note);}list=new ListView(host);list.setDivider(new android.graphics.drawable.ColorDrawable(AppUi.BG));list.setDividerHeight(AppUi.dp(host,10));list.setSelector(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));addView(list,new LayoutParams(-1,0,1));}
        if(snapshot!=null)rows();}
    private void mode(boolean song,int chart){single=song;cid=chart;remember.accept(single,cid);build();load(false);}
    private void load(boolean force){
        if(closed)return;
        final int request=++loadGeneration,requested=single?cid:0;
        if(single&&cid==0){loading=false;refresh.setEnabled(false);status.setText("选择歌曲后读取对应单曲榜");return;}
        loading=true;refresh.setEnabled(false);if(snapshot!=null&&snapshot.cid!=requested)snapshot=null;if(list!=null&&snapshot==null)list.setAdapter(null);status.setText("读取云端排行索引…");
        io.execute(()->{try{RankingRepository.Snapshot cache=RankingRepository.cached(host,engine,requested);if(cache!=null)deliver(()->{if(request!=loadGeneration)return;snapshot=cache;rows();status.setText("正在刷新 · "+stamp(cache.updated));});RankingRepository.Snapshot next=RankingRepository.refresh(host,engine,force,requested,message->deliver(()->{if(request==loadGeneration)status.setText(message);}));deliver(()->{if(request!=loadGeneration)return;snapshot=next;loading=false;refresh.setEnabled(true);rows();});}catch(Exception e){deliver(()->{if(request!=loadGeneration)return;loading=false;refresh.setEnabled(true);status.setText((snapshot!=null?"刷新未完成，显示缓存。":"无法读取排行榜。")+(e.getMessage()==null?"请重试":e.getMessage()));});}});
    }
    private void deliver(Runnable action){host.runOnUiThread(()->{if(!closed&&!host.isDestroyed())action.run();});}
    private static String stamp(long time){SimpleDateFormat f=new SimpleDateFormat("MM-dd HH:mm",Locale.CHINA);f.setTimeZone(TimeZone.getTimeZone("Asia/Shanghai"));return f.format(new Date(time));}
    private void rows(){if(snapshot==null||snapshot.cid!=(single?cid:0))return;status.setText((snapshot.cached?"缓存 · ":"更新 · ")+stamp(snapshot.updated)+" · "+snapshot.players.size()+" 位玩家 · 当前谱库索引"+(snapshot.failed>0?" · "+snapshot.failed+"份存档未更新，排行可能不完整":""));if(list==null)return;
        List<RankingData.Player> totals=RankingData.total(snapshot.players);List<RankingData.Score> scores=single?RankingData.chart(snapshot.players,cid):Collections.emptyList();int count=Math.min(50,single?scores.size():totals.size());
        if(count==0){list.setAdapter(new ArrayAdapter<>(host,android.R.layout.simple_list_item_1,new String[]{"暂无已发布排行，请先合并同步云端成绩"}));return;}
        list.setAdapter(new BaseAdapter(){public int getCount(){return count;}public Object getItem(int position){return single?scores.get(position):totals.get(position);}public long getItemId(int pos){return pos;}public android.view.View getView(int position,android.view.View recycled,android.view.ViewGroup parent){LinearLayout row=AppUi.column(host,14);row.setBackground(AppUi.background(host,AppUi.CARD));String qq,name;int rank;double rating;if(single){RankingData.Score s=scores.get(position);qq=s.qq;name=s.name;rank=s.rank;rating=s.rating;}else{RankingData.Player p=totals.get(position);qq=p.qq;name=p.name;rank=p.rank;rating=p.rating;}if(qq.equals(ScoreStore.profile(host)))row.setBackground(AppUi.background(host,AppUi.SELECTED));LinearLayout top=new LinearLayout(host);top.setGravity(Gravity.CENTER_VERTICAL);TextView place=AppUi.text(host,"#"+rank,21,rank<=3?AppUi.GOLD:AppUi.MUTED,true);top.addView(place,new LayoutParams(AppUi.dp(host,56),-2));TextView player=AppUi.text(host,name,17,AppUi.INK,true);player.setMaxLines(2);top.addView(player,new LayoutParams(0,-2,1));row.addView(top);AppUi.space(row,6);row.addView(AppUi.text(host,"QQ "+qq,12,AppUi.MUTED,false));row.addView(AppUi.text(host,String.format(Locale.ROOT,"rating %.4f",rating),23,AppUi.ACCENT,true));if(single){RankingData.Score s=scores.get(position);row.addView(AppUi.text(host,String.format(Locale.ROOT,"准度 %.3f%% · %,d · %s",s.accuracy,s.score,RatingRules.judgeName(s.judge)),14,AppUi.MUTED,false));}else{RankingData.Player p=totals.get(position);row.addView(AppUi.text(host,String.format(Locale.ROOT,"O20 %.4f · N10 %.4f",p.oldRating,p.newRating),14,AppUi.MUTED,false));}return row;}});
    }
    public boolean backToChooser(){if(single&&cid>0){mode(true,0);return true;}return false;}
    public void close(){closed=true;io.shutdown();}
}
